(function() {
    'use strict';

    class TrianguloFuegoAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Triángulo de Fuego';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    showEVM: false,
                    panelId: 'round1Decisions'
                },
                {
                    showEVM: true,
                    panelId: 'round2Decisions'
                },
                {
                    showEVM: true,
                    panelId: 'round3Decisions'
                },
                {
                    showEVM: true,
                    panelId: 'round4Decisions'
                }
            ];
        }

        _getBriefing(idx, lang) {
            var en = [
                '<b>Month 0–3: Project Launch</b><br><br>You are the Project Director of Constructora MetroAndes S.A. de C.V., managing the rehabilitation of Mercado Tepito in Mexico City. Contract value: MXN 187M (fixed-price). Deadline: 14 months (Bicentennial). Performance bonus: MXN 8M if on time. Penalty: MXN 3.5M/month for delays.<br><br><b>Your project baseline:</b><br>• 42 deliverables across 8 work packages<br>• Critical path: 420 days (zero float)<br>• Contingency reserve: MXN 12M (6.4% — thin by industry standards)<br>• 5 identified risks in the risk register<br><br>Set your project planning parameters for the first phase.',
                '<b>Month 4–6: EVM Review</b><br><br>Six months into execution. The EVM dashboard reveals concerning metrics. Two scope change requests have arrived:<br><br><b>SCR #1 (INAH):</b> Heritage authority requires expanded colonial facade restoration. Legal compliance obligation.<br><b>SCR #2 (Vendors):</b> Vendor association requests 14 additional market stalls. Political pressure from CDMX.<br><br>Your electrical subcontractor is requesting an 18% price increase mid-contract. The project is behind schedule and over budget. What is your recovery strategy?',
                '<b>Month 7–9: Crisis Mode</b><br><br>The project is in serious trouble. Structural reinforcement took 102 days vs. planned 85 — a 20% overrun on the critical path. Two resource conflicts demand immediate resolution:<br><br><b>Scaffolding crisis:</b> Structural and electrical teams compete for scaffold towers (8 available, 14 needed).<br><b>Leadership gap:</b> Star project manager Ing. García has left for a competitor.<br><br>EVM indicators continue to decline. Every decision now directly impacts the Bicentennial deadline.',
                '<b>Month 10–14: The Final Sprint</b><br><br>Three months remain until the Bicentennial deadline. The project must make critical quality vs. speed trade-offs. The heritage facade status, remaining punch list items, and political pressure converge in this final phase.<br><br>You must decide: deliver a complete project late, or a partially complete project on time? The MXN 8M bonus and MXN 3.5M/month penalty hang in the balance.<br><br>Make your final decisions to close the project.'
            ];
            var es = [
                '<b>Mes 0–3: Lanzamiento del Proyecto</b><br><br>Eres el Director de Proyecto de Constructora MetroAndes S.A. de C.V., gestionando la rehabilitación del Mercado Tepito en Ciudad de México. Valor del contrato: MXN 187M (precio fijo). Plazo: 14 meses (Bicentenario). Bono: MXN 8M si se entrega a tiempo. Penalización: MXN 3.5M/mes de retraso.<br><br><b>Línea base del proyecto:</b><br>• 42 entregables en 8 paquetes de trabajo<br>• Ruta crítica: 420 días (holgura cero)<br>• Reserva de contingencia: MXN 12M (6.4%)<br>• 5 riesgos identificados en el registro de riesgos<br><br>Establece los parámetros de planificación para la primera fase.',
                '<b>Mes 4–6: Revisión EVM</b><br><br>Seis meses de ejecución. El panel EVM revela métricas preocupantes. Han llegado dos solicitudes de cambio de alcance:<br><br><b>SCR #1 (INAH):</b> La autoridad de patrimonio requiere restauración expandida de la fachada colonial. Obligación legal.<br><b>SCR #2 (Vendedores):</b> La asociación de vendedores solicita 14 puestos adicionales. Presión política de la CDMX.<br><br>El subcontratista eléctrico solicita un aumento del 18%. El proyecto está atrasado y sobre presupuesto.',
                '<b>Mes 7–9: Modo Crisis</b><br><br>El proyecto está en serios problemas. El refuerzo estructural tomó 102 días vs. 85 planificados — sobrecosto del 20% en ruta crítica. Dos conflictos de recursos:<br><br><b>Crisis de andamios:</b> Los equipos estructural y eléctrico compiten por torres de andamio (8 disponibles, 14 necesarias).<br><b>Vacante de liderazgo:</b> Ing. García se fue a la competencia.<br><br>Los indicadores EVM continúan deteriorando. Cada decisión impacta el plazo del Bicentenario.',
                '<b>Mes 10–14: El Sprint Final</b><br><br>Quedan tres meses hasta el Bicentenario. El proyecto debe conciliar calidad y velocidad. La fachada patrimonial, los pendientes y la presión política convergen.<br><br>Debes decidir: entregar un proyecto completo tarde, o parcialmente completo a tiempo. El bono de MXN 8M y la penalización de MXN 3.5M/mes están en juego.<br><br>Toma tus decisiones finales para cerrar el proyecto.'
            ];
            var i = Math.min(idx, 3);
            return (lang === 'es') ? es[i] : en[i];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 187000000,
                    contingencyReserve: 12000000,
                    totalSpent: 0,
                    scheduleDaysTotal: 420,
                    scheduleDaysAdded: 0,
                    scopeItemsTotal: 42,
                    scopeItemsCompleted: 0,
                    scopeItemsAdded: 0,
                    spi: 1.00,
                    cpi: 1.00,
                    pv: 0,
                    ev: 0,
                    ac: 0,
                    stakeholderCDMX: 75,
                    stakeholderVendors: 70,
                    stakeholderINAH: 70,
                    riskMitigationInvestment: 0,
                    methodology: 'waterfall',
                    commFrequency: 'biweekly',
                    bonusEligible: true,
                    penaltyMonths: 0,
                    archaeologicalTriggered: false,
                    steelSpikeTriggered: false,
                    electionTriggered: false,
                    accidentTriggered: false,
                    inahPreviewTriggered: false,
                    fastTrackUsed: false,
                    rebaselined: false,
                    spiHistory: [],
                    cpiHistory: [],
                    budgetHistory: [],
                    scopeHistory: [],
                    stakeholderHistory: [],
                    scoreHistory: [],
                    contingencyRemaining: 12000000,
                    majorEventCount: 0,
                    reserveBlown: false,
                    finalOnTime: false,
                    finalTotalDays: 420
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    contingency: 12,
                    riskMitigation: 5,
                    methodology: 'waterfall',
                    commFrequency: 'biweekly',
                    scopeChange1: 'negotiate',
                    scopeChange2: 'reject',
                    scheduleRecovery: 'crash',
                    scaffolding: 'rent',
                    pmReplacement: 'internal',
                    qualityFocus: 50,
                    punchList: 'partial'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            var fwLang = window.mySimulation && (window.mySimulation.lang || window.mySimulation.currentLanguage);
            if (fwLang) {
                lang = fwLang;
            } else {
                var htmlLang = document.documentElement.lang;
                if (htmlLang) lang = htmlLang;
            }
            lang = (String(lang).substring(0, 2) === 'es') ? 'es' : 'en';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._getBriefing(idx, lang);

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            var evmPanel = document.getElementById('evmPanel');
            if (evmPanel) evmPanel.style.display = round.showEVM ? 'block' : 'none';

            if (round.showEVM && state.domainState) {
                var ds = state.domainState;
                var pvEl = document.getElementById('pvDisplay');
                var evEl = document.getElementById('evDisplay');
                var acEl = document.getElementById('acDisplay');
                var eacEl = document.getElementById('eacDisplay');
                var fmt = function(v) { return '$' + Math.round(v / 1000000) + 'M'; };
                if (pvEl) pvEl.textContent = fmt(ds.pv);
                if (evEl) evEl.textContent = fmt(ds.ev);
                if (acEl) acEl.textContent = fmt(ds.totalSpent);
                var eac = ds.cpi > 0 ? 187000000 / ds.cpi : 0;
                if (eacEl) eacEl.textContent = fmt(eac);
            }
        }

        validateDecisions(decisions) {
            var period = 1;
            if (window.mySimulation && window.mySimulation.state) {
                period = window.mySimulation.state.currentPeriod;
                this._updateBriefing(window.mySimulation.state);
            }

            if (period === 1) {
                var cInput = document.getElementById('contingencyInput');
                if (cInput) decisions.contingency = parseInt(cInput.value);
                var rmInput = document.getElementById('riskMitigationInput');
                if (rmInput) decisions.riskMitigation = parseFloat(rmInput.value);
                var mInput = document.getElementById('methodologyInput');
                if (mInput) decisions.methodology = mInput.value;
                var cfInput = document.getElementById('commFrequencyInput');
                if (cfInput) decisions.commFrequency = cfInput.value;
                if (isNaN(decisions.riskMitigation) || decisions.riskMitigation < 0 || decisions.riskMitigation > 15) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('risk_mitigation_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var sc1 = document.getElementById('scopeChange1Input');
                if (sc1) decisions.scopeChange1 = sc1.value;
                var sc2 = document.getElementById('scopeChange2Input');
                if (sc2) decisions.scopeChange2 = sc2.value;
                var sr = document.getElementById('scheduleRecoveryInput');
                if (sr) decisions.scheduleRecovery = sr.value;
            } else if (period === 3) {
                var scaf = document.getElementById('scaffoldingInput');
                if (scaf) decisions.scaffolding = scaf.value;
                var pm = document.getElementById('pmReplacementInput');
                if (pm) decisions.pmReplacement = pm.value;
            } else if (period === 4) {
                var qf = document.getElementById('qualityFocusInput');
                if (qf) decisions.qualityFocus = parseInt(qf.value);
                var pl = document.getElementById('punchListInput');
                if (pl) decisions.punchList = pl.value;
                if (isNaN(decisions.qualityFocus) || decisions.qualityFocus < 0 || decisions.qualityFocus > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('quality_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            var d = state.decisions;
            var period = state.currentPeriod;
            var events = [];
            var periodCost = 0;
            var daysAdded = 0;
            var scopeAdded = 0;
            var scopeCompleted = 0;
            var stDelta = { cdmx: 0, vendors: 0, inah: 0 };

            if (period === 1) {
                ds.contingencyReserve = d.contingency * 1000000;
                ds.contingencyRemaining = ds.contingencyReserve;
                ds.majorEventCount = 0;
                ds.reserveBlown = false;
                ds.riskMitigationInvestment = d.riskMitigation * 1000000;
                periodCost += ds.riskMitigationInvestment;
                periodCost += 15000000;
                periodCost += Math.round((d.contingency - 12) * 1000000 * 0.12);

                ds.methodology = d.methodology;
                if (d.methodology === 'agile') periodCost += 850000;
                else if (d.methodology === 'hybrid') periodCost += 425000;

                ds.commFrequency = d.commFrequency;
                if (d.commFrequency === 'weekly') {
                    stDelta.cdmx = 5; stDelta.vendors = 3; stDelta.inah = 4;
                } else if (d.commFrequency === 'biweekly') {
                    stDelta.cdmx = 2; stDelta.vendors = 1; stDelta.inah = 2;
                } else {
                    stDelta.cdmx = -2; stDelta.vendors = -3; stDelta.inah = 0;
                }

                scopeCompleted = 0;
                ds.spi = 1.00;
                ds.cpi = 1.00;
                ds.pv = 187000000 * 0.10;
                ds.ev = 0;
                ds.ac = periodCost;

                if (Math.random() < 0.40) {
                    ds.inahPreviewTriggered = true;
                    events.push(window.mySimulation.t('event_inah_preview'));
                    stDelta.inah -= 5;
                }

            } else if (period === 2) {
                var baseSPI = 0.89;
                var baseCPI = 0.91;
                scopeCompleted = 19;
                periodCost = 70000000;

                var archProb = 0.30 - (ds.riskMitigationInvestment >= 8000000 ? 0.10 : 0);
                if (Math.random() < archProb) {
                    ds.archaeologicalTriggered = true;
                    periodCost += 8500000;
                    daysAdded += 45;
                    scopeCompleted -= 4;
                    ds.contingencyRemaining -= 8500000;
                    ds.majorEventCount++;
                    events.push(window.mySimulation.t('event_archaeological'));
                    baseSPI -= 0.06;
                    baseCPI -= 0.04;
                    stDelta.inah += 5;
                }

                var steelProb = 0.35 - (ds.riskMitigationInvestment >= 5000000 ? 0.15 : 0);
                if (Math.random() < steelProb) {
                    ds.steelSpikeTriggered = true;
                    periodCost += 6800000;
                    ds.contingencyRemaining -= 6800000;
                    ds.majorEventCount++;
                    events.push(window.mySimulation.t('event_steel_spike'));
                    baseCPI -= 0.03;
                }

                if (d.scopeChange1 === 'approve') {
                    periodCost += 5800000; daysAdded += 35; scopeAdded += 3;
                    stDelta.inah += 12; stDelta.cdmx -= 3;
                    baseSPI -= 0.03; baseCPI -= 0.02;
                } else if (d.scopeChange1 === 'negotiate') {
                    periodCost += 3200000; daysAdded += 18; scopeAdded += 2;
                    stDelta.inah += 6;
                    baseSPI -= 0.01; baseCPI -= 0.01;
                } else {
                    stDelta.inah -= 15; stDelta.cdmx -= 5;
                    events.push(window.mySimulation.t('event_inah_sanction_risk'));
                }

                var vendorCost = 0;
                if (d.scopeChange2 === 'approve') {
                    vendorCost = 3100000;
                    if (ds.methodology === 'agile') vendorCost = Math.round(vendorCost * 0.35);
                    else if (ds.methodology === 'hybrid') vendorCost = Math.round(vendorCost * 0.60);
                    periodCost += vendorCost;
                    daysAdded += (ds.methodology === 'agile' ? 7 : ds.methodology === 'hybrid' ? 12 : 20);
                    scopeAdded += 5; stDelta.vendors += 15; stDelta.cdmx += 5;
                    baseSPI -= 0.02;
                } else if (d.scopeChange2 === 'negotiate') {
                    vendorCost = 1600000;
                    if (ds.methodology === 'agile') vendorCost = Math.round(vendorCost * 0.35);
                    else if (ds.methodology === 'hybrid') vendorCost = Math.round(vendorCost * 0.60);
                    periodCost += vendorCost;
                    daysAdded += (ds.methodology === 'agile' ? 4 : ds.methodology === 'hybrid' ? 6 : 10);
                    scopeAdded += 3; stDelta.vendors += 8;
                    baseSPI -= 0.01;
                } else {
                    stDelta.vendors -= 12; stDelta.cdmx -= 2;
                }

                if (d.scheduleRecovery === 'crash') {
                    periodCost += 4200000; daysAdded -= 15;
                    baseSPI += 0.04; baseCPI -= 0.02;
                } else if (d.scheduleRecovery === 'fasttrack') {
                    daysAdded -= 12;
                    baseSPI += 0.03;
                    ds.fastTrackUsed = true;
                } else {
                    stDelta.cdmx -= 10;
                    ds.bonusEligible = false;
                    ds.rebaselined = true;
                    events.push(window.mySimulation.t('event_rebaseline'));
                }

                periodCost += 2100000;

                ds.pv = 187000000 * 0.50;
                var evDone2 = ds.scopeItemsCompleted + scopeCompleted;
                var evTotal2 = ds.scopeItemsTotal + ds.scopeItemsAdded + scopeAdded;
                var evAC2 = ds.totalSpent + periodCost;
                ds.ev = 187000000 * (evTotal2 > 0 ? Math.max(0, evDone2) / evTotal2 : 0);
                ds.ac = evAC2;
                ds.spi = Math.round(Math.max(0.50, Math.min(1.30, ds.pv > 0 ? ds.ev / ds.pv : 1)) * 100) / 100;
                ds.cpi = Math.round(Math.max(0.50, Math.min(1.30, evAC2 > 0 ? ds.ev / evAC2 : 1)) * 100) / 100;

            } else if (period === 3) {
                var baseSPI3 = ds.spi - 0.06;
                var baseCPI3 = ds.cpi - 0.03;
                scopeCompleted = 11;
                periodCost = 45000000;

                daysAdded += 17;
                periodCost += 2800000;

                if (d.scaffolding === 'buy') {
                    periodCost += 1800000;
                    baseSPI3 += 0.02;
                } else if (d.scaffolding === 'rent') {
                    periodCost += 900000;
                    daysAdded += 5;
                    baseSPI3 += 0.01;
                } else {
                    daysAdded += 25;
                    baseSPI3 -= 0.05;
                }

                if (d.pmReplacement === 'internal') {
                    stDelta.cdmx -= 5; stDelta.vendors -= 3;
                    scopeCompleted -= 1;
                } else if (d.pmReplacement === 'external') {
                    periodCost += 600000;
                    daysAdded += 15;
                    stDelta.cdmx += 3;
                    baseCPI3 -= 0.01;
                    scopeCompleted += 1;
                } else {
                    stDelta.cdmx -= 2;
                }

                if (ds.fastTrackUsed && Math.random() < 0.30) {
                    periodCost += 1500000;
                    daysAdded += 8;
                    events.push(window.mySimulation.t('event_fasttrack_rework'));
                    ds.contingencyRemaining -= 1500000;
                    ds.majorEventCount++;
                    baseSPI3 -= 0.02;
                }

                if (Math.random() < 0.20) {
                    ds.electionTriggered = true;
                    stDelta.cdmx -= 8;
                    events.push(window.mySimulation.t('event_election'));
                }

                ds.pv = 187000000 * 0.78;
                var evDone3 = ds.scopeItemsCompleted + scopeCompleted;
                var evTotal3 = ds.scopeItemsTotal + ds.scopeItemsAdded + scopeAdded;
                var evAC3 = ds.totalSpent + periodCost;
                ds.ev = 187000000 * (evTotal3 > 0 ? Math.max(0, evDone3) / evTotal3 : 0);
                ds.ac = evAC3;
                ds.spi = Math.round(Math.max(0.50, Math.min(1.30, ds.pv > 0 ? ds.ev / ds.pv : 1)) * 100) / 100;
                ds.cpi = Math.round(Math.max(0.50, Math.min(1.30, evAC3 > 0 ? ds.ev / evAC3 : 1)) * 100) / 100;

            } else if (period === 4) {
                var qualityRatio = d.qualityFocus / 100;
                var speedRatio = 1 - qualityRatio;
                var remaining = (ds.scopeItemsTotal + ds.scopeItemsAdded) - ds.scopeItemsCompleted;
                periodCost = 30000000;

                if (d.punchList === 'complete') {
                    scopeCompleted = remaining;
                    daysAdded += 15;
                    periodCost += 2500000;
                    stDelta.cdmx += 5; stDelta.inah += 8;
                } else if (d.punchList === 'partial') {
                    scopeCompleted = Math.round(remaining * (0.80 + qualityRatio * 0.15));
                    daysAdded += 5;
                    periodCost += 1200000;
                    stDelta.cdmx += 2;
                } else {
                    scopeCompleted = Math.round(remaining * (0.65 + qualityRatio * 0.15));
                    stDelta.cdmx -= 5; stDelta.inah -= 10; stDelta.vendors += 3;
                }

                daysAdded -= Math.round(speedRatio * 15);
                periodCost += Math.round(speedRatio * 3000000);

                if (Math.random() < 0.15) {
                    ds.accidentTriggered = true;
                    daysAdded += 10;
                    periodCost += 500000;
                    scopeCompleted -= 1;
                    ds.contingencyRemaining -= 500000;
                    ds.majorEventCount++;
                    events.push(window.mySimulation.t('event_accident'));
                }

                var totalDaysUsed = 420 + ds.scheduleDaysAdded + daysAdded;
                var onTime = totalDaysUsed <= 420;
                if (!onTime && !ds.rebaselined) {
                    var delayMonths = Math.ceil((totalDaysUsed - 420) / 30);
                    ds.penaltyMonths = delayMonths;
                    ds.bonusEligible = false;
                    periodCost += delayMonths * 3500000;
                }
                if (ds.bonusEligible && onTime) {
                    periodCost -= 8000000;
                    events.push(window.mySimulation.t('event_bonus'));
                }
                ds.finalOnTime = onTime;
                ds.finalTotalDays = totalDaysUsed;

                var totalScope = ds.scopeItemsTotal + ds.scopeItemsAdded + scopeAdded;
                var finalComplete = ds.scopeItemsCompleted + scopeCompleted;
                var finalScopePct = totalScope > 0 ? Math.max(0, finalComplete) / totalScope : 0;
                var totalCost = ds.totalSpent + periodCost;
                var finalSPI = onTime ? 1.00 : Math.max(0.50, 420 / totalDaysUsed);
                var finalCPI = totalCost > 0 ? (187000000 * finalScopePct) / totalCost : 1;

                ds.spi = Math.round(Math.max(0.50, Math.min(1.30, finalSPI)) * 100) / 100;
                ds.cpi = Math.round(Math.max(0.50, Math.min(1.30, finalCPI)) * 100) / 100;
                ds.pv = 187000000;
                ds.ev = 187000000 * finalScopePct;
                ds.ac = totalCost;
            }

            ds.totalSpent += periodCost;
            ds.scheduleDaysAdded += daysAdded;
            ds.scopeItemsAdded += scopeAdded;
            ds.scopeItemsCompleted += scopeCompleted;

            if (ds.contingencyRemaining < 0 && !ds.reserveBlown) {
                ds.reserveBlown = true;
                stDelta.cdmx -= 6;
                events.push(window.mySimulation.t('event_reserve_blown'));
            }
            ds.stakeholderCDMX = Math.max(0, Math.min(100, ds.stakeholderCDMX + stDelta.cdmx));
            ds.stakeholderVendors = Math.max(0, Math.min(100, ds.stakeholderVendors + stDelta.vendors));
            ds.stakeholderINAH = Math.max(0, Math.min(100, ds.stakeholderINAH + stDelta.inah));

            var avgStake = Math.round((ds.stakeholderCDMX + ds.stakeholderVendors + ds.stakeholderINAH) / 3);
            var totalScope = ds.scopeItemsTotal + ds.scopeItemsAdded;
            var scopePct = totalScope > 0 ? Math.round((ds.scopeItemsCompleted / totalScope) * 100) : 0;
            var budgetRemaining = ds.budget - ds.totalSpent;

            var clampScore = function(x) { return Math.max(0, Math.min(100, Math.round(x))); };
            var lin = function(x, lo, hi) { return clampScore((x - lo) / (hi - lo) * 100); };

            var costScore = lin(ds.cpi, 0.70, 1.05);
            var plannedPct = (period === 1) ? 0.10 : (period === 2) ? 0.50 : (period === 3) ? 0.78 : 1.00;
            var schedScore, scpScore;
            if (period < 4) {
                schedScore = lin(ds.spi, 0.58, 1.00);
                scpScore = lin(plannedPct > 0 ? scopePct / (plannedPct * 100) : 0, 0.70, 1.05);
            } else {
                if (ds.finalOnTime) {
                    schedScore = 100;
                } else {
                    var lateDays = Math.max(0, ds.finalTotalDays - 420);
                    schedScore = clampScore(100 - lateDays * 0.8);
                    if (ds.rebaselined) schedScore = Math.min(schedScore, 55);
                }
                scpScore = lin(scopePct, 70, 100);
            }
            var stkScore = lin(avgStake, 40, 85);
            var rskScore = 30;
            if (ds.riskMitigationInvestment >= 8000000) rskScore += 25;
            else if (ds.riskMitigationInvestment >= 5000000) rskScore += 15;
            if (!ds.reserveBlown) rskScore += 20;
            if (ds.majorEventCount === 0) rskScore += 15;
            else if (ds.majorEventCount === 1) rskScore += 7;
            if (ds.methodology !== 'waterfall') rskScore += 10;
            rskScore = clampScore(rskScore);

            var composite = Math.round(
                schedScore * 0.30 + costScore * 0.25 + scpScore * 0.20 + stkScore * 0.15 + rskScore * 0.10
            );

            ds.spiHistory.push(ds.spi);
            ds.cpiHistory.push(ds.cpi);
            ds.budgetHistory.push(budgetRemaining);
            ds.scopeHistory.push(scopePct);
            ds.stakeholderHistory.push(avgStake);
            ds.scoreHistory.push(composite);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
                var eventPanel = document.getElementById('eventLogPanel');
                var eventText = document.getElementById('eventLogText');
                if (events.length > 0 && eventPanel && eventText) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = events.join('<br>');
                } else if (eventPanel) {
                    eventPanel.style.display = 'none';
                }
            }, 500);

            return {
                period: period,
                spi: ds.spi,
                cpi: ds.cpi,
                budgetRemaining: budgetRemaining,
                scopeComplete: scopePct,
                stakeholderScore: avgStake,
                periodCost: periodCost,
                compositeScore: composite,
                eventsText: events.join('; ') || 'None'
            };
        }

